#include<bits/stdc++.h>
using namespace std;const int N=12;double R[N][N],z[N];long long G[N][N],nodes=0;int mins[4096],w[4096][N];
void go(int k,double q){nodes++;if(k<0){int mask=0;long long Q=0;for(int i=0;i<N;i++){mask|=((int)z[i]&1)<<i;for(int j=0;j<N;j++)Q+=(long long)z[i]*G[i][j]*(long long)z[j];}if(Q<mins[mask]){mins[mask]=Q;for(int i=0;i<N;i++)w[mask][i]=z[i];}return;}double a=0;for(int j=k+1;j<N;j++)a-=R[k][j]*z[j]/R[k][k];double rad=sqrt(max(0.,16.00000001-q))/R[k][k];for(int x=ceil(a-rad-1e-8);x<=floor(a+rad+1e-8);x++){z[k]=x;double v=R[k][k]*(a-x);if(q+v*v<=16.00000001)go(k-1,q+v*v);}}
int main(){ifstream f("research/ct36_contact_walk_20261112/spectator_R.txt"),g("research/ct36_contact_walk_20261112/spectator_G.txt");for(auto&a:R)for(auto&v:a)f>>v;for(auto&a:G)for(auto&v:a)g>>v;fill(mins,mins+4096,999);go(N-1,0);ofstream o("research/ct36_contact_walk_20261112/spectator_witnesses.txt");map<int,int>hist;for(int i=0;i<4096;i++){hist[mins[i]]++;o<<i<<' '<<mins[i];for(auto a:w[i])o<<' '<<a;o<<endl;}cout<<"nodes "<<nodes<<endl;for(auto[a,b]:hist)cout<<a<<' '<<b<<endl;}
